{
 "research_concepts": ["cut-heavy shapers", "drive-heavy players", "structural roles", "role portability across contexts", "play-type possession records", "regular season to playoff transfer"],
 "methodological_questions": [
  "Can cut-share versus drive-share be measured reliably from play-by-play labels without foul-ending or OTHER-bucket contamination?",
  "Is n=24 units enough to detect a portability difference between cut-heavy and drive-heavy shapers?",
  "Can role portability be defined so that it is not derived from the outcome it is meant to predict?",
  "Do regular-season and playoff play-type labels share the same tagging behaviour, so that a cross-context comparison is valid?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-CHT-057",
   "status_as_recorded": "supported",
   "finding": "Cut- vs drive-based connector portability on 92 connector movers: cut share rho=+0.265 p=0.011 (AUC 0.653); cut-drive rho=+0.314 p=0.002; drive rho=-0.278 p=0.007; top cut tercile 65% portable (median Delta +0.167) vs bottom 35% (median -0.039); LOO AUC 0.622; permutation p=0.005. Its recorded limitation is LIM:small_sample with RISK:SAMPLE_SIZE_POWER."
  },
  {
   "id": "FAM:SF-APPS-011",
   "status_as_recorded": "supported",
   "finding": "Regular-season vs playoff PPP by play type across 25 teams (min 30 possessions per cell, no CIs): DRIVE RS 1.198 vs PO 0.912 (-0.286); PNR -0.173; PULL_UP +0.301; other types within -0.07."
  },
  {
   "id": "FAM:SF-CHT-025",
   "status_as_recorded": "artifact",
   "finding": "Play-type labeling audit found OTHER with 36% foul endings (PPP inflated), DRIVE 12pp below the foul benchmark, and only 335 of 50,668 possessions (0.7%) mapping to a real play type via initiation_type. Recorded verdict: artifact_found."
  },
  {
   "id": "FAM:SF-APPM-014",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Play-type label accuracy audit failed overall (verdict tool_eval_fail): OTHER 20.2% against a <10% target, 40.8% low confidence, DRIVE foul-draw 1.7% against a 14-22% benchmark, and identity checks failed for MIA."
  },
  {
   "id": "FAM:SF-CHT-087",
   "status_as_recorded": "artifact",
   "finding": "Connector-mover pairing variants: the population-level KW p=0.047 was the only stratified result; the organizer-connector gap CI includes 0 after correcting a menu-similarity confound (recorded LIM:confounding, LIM:small_sample)."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "Persistent Impact Score Level 1 gate (verdict failed_gate): DRIVE lifts were flat across lags (+0.015 to +0.021) with Cohen d about 0.01-0.03, and collapsed under a within-team baseline; recorded as a team-quality confound on n>150k possessions."
  },
  {
   "id": "FAM:SF-APPS-010",
   "status_as_recorded": "inconclusive",
   "finding": "Play-type PPP across playoff series game buckets (1197 records, no CIs): DRIVE 0.889 to 0.949 (+0.060); the recorded signal was 'NO CLEAR SIGNAL'; recorded limitation LIM:selection_or_regression_to_the_mean."
  },
  {
   "id": "FAM:SF-APPS-012",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Defensive PPP allowed and possession share, RS vs playoffs, across 25 teams: DRIVE allowed 1.191 to 0.923; PNR share +12.1pp, which the record says may reflect tagging differences; no inferential test."
  },
  {
   "id": "FAM:SF-CHT-052",
   "status_as_recorded": "inconclusive",
   "finding": "Play-type replacement similarity vs absorb/cascade: mean similarity ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19, wrong-signed. Recorded failure type B_powered_null, with LIM:label_or_classification_error."
  },
  {
   "id": "FAM:SF08",
   "status_as_recorded": "untestable",
   "finding": "Season adapter profiles: BEST-share vs playoff winning. Recorded as A_unanswerable, with LIM:confounding, LIM:small_sample, RISK:CONFOUNDING and RISK:SAMPLE_SIZE_POWER."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-CHT-025",
   "what_failed": "Mapping play types from initiation_type and reading PPP differences between play types as real efficiency.",
   "why": "OTHER PPP was inflated by 36% foul endings, DRIVE was 12pp below the foul benchmark, and only 0.7% of possessions mapped to a real play type."
  },
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Play-type label accuracy and distribution audit used as a basis for adaptation findings.",
   "why": "Recorded systematic issues: OTHER 20.2% against a <10% target, 40.8% low confidence, DRIVE foul-draw 1.7% against a 14-22% benchmark, foul possessions leaking into OTHER, and failed MIA identity checks."
  },
  {
   "id": "FAM:SF-CHT-087",
   "what_failed": "Connector-mover pairing by name-keyed vs franchise rules, with a population-level role-class stratification.",
   "why": "Recorded menu-similarity confounding; the organizer-connector CI includes 0 after correction; the KW p=0.047 is population-level and the pairwise result is only suggestive."
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Testing decaying cross-possession memory of play-type actions (lag-1 vs lag-2).",
   "why": "Flat non-decaying lifts; within-team baseline collapsed the effect; team-quality confound recorded; effect sizes were negligible (Cohen d about 0.01-0.03) despite very large n."
  },
  {
   "id": "FAM:SF08",
   "what_failed": "Season-level BEST-share as a predictor of playoff winning.",
   "why": "Recorded as unanswerable with the data or design; confounding and small sample."
  }
 ],
 "evidence_establishes": [
  "Within the project's earlier connector work (FAM:SF-CHT-057), cut-share was positively associated with reproduced organizational function after a move (rho=+0.265, p=0.011, n=92 movers), and drive-share was negatively associated. This is a different population and unit from the present question.",
  "Play-type labels derived from this pipeline have documented systematic errors (FAM:SF-CHT-025, FAM:SF-APPM-014). OTHER and DRIVE shares are contaminated by foul endings and tagging, so any cut/drive share built from these labels carries measurement risk.",
  "Drive PPP fell between regular season and playoffs in an earlier 25-team descriptive comparison (FAM:SF-APPS-011), but that record has no CIs and its own status is supported, not a validated portability test."
 ],
 "evidence_does_not_establish": [
  "Whether cut-heavy shapers' roles travel better than drive-heavy ones in the present n=24 unit set. No retrieved record tested this on units of the present type.",
  "The direction or size of any cut-vs-drive portability difference at n=24. The one supported result rests on 92 movers, and no record reports a power analysis for n=24.",
  "Whether cut and drive shares are valid measures. The labeling audits (FAM:SF-CHT-025, FAM:SF-APPM-014) argue against trusting them without repair.",
  "Whether the regular-season-to-playoff context shift is a valid form of role portability, since the descriptive records do not separate tagging change from real behaviour change (FAM:SF-APPS-012)."
 ],
 "own_inferences": [
  "The retrieved records do not directly test the stated question with the stated units. The closest record (FAM:SF-CHT-057) uses a different unit, a different sample size, and a connector construct rather than 'shapers'.",
  "With n=24 units, a two-sided Spearman test at alpha 0.05 and 80% power only detects |rho| of about 0.54 or larger, so a modest effect of the size seen in FAM:SF-CHT-057 would almost certainly be missed.",
  "Cut and drive shares are likely both affected by the OTHER/foul leakage recorded in FAM:SF-CHT-025, which could bias the comparison in an unknown direction if foul-draw rates differ by player type.",
  "The question's wording ('shapers', 'roles travel') does not state an operational definition of portability, so the estimand is underspecified before any analysis."
 ],
 "uncertainties": [
  "The definition of 'shapers', 'roles' and 'travel' is not in the task statement; the portability metric is assumed, not given.",
  "The composition of the 24 units (teams, players, or player-seasons) is not stated. The power estimate assumes independent units.",
  "The per-game files do not contain tracking data, so cut and drive cannot be validated against a gold-standard tag.",
  "The 2025-26 playoff file is complete only from 2026-06-21; it is treated as complete at the 2026-08-08 decision date.",
  "No record in the retrieval reports a CI or power calculation for a cut-vs-drive portability test at n=24."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "Retrieved records showed that the closest prior test (FAM:SF-CHT-057) was supported only at n=92 with a different construct, and that play-type labels, which any cut/drive measure would rely on, failed audits (FAM:SF-CHT-025, FAM:SF-APPM-014). Together with the low power at n=24 that I computed, this moved the decision from a possible proceed to do_not_proceed as posed."
 },
 "testability": {
  "p_testable": 0.1,
  "blocking_constraints": [
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "n=24 units gives power only for |rho| of about 0.54 or larger; the prior supported effect came from 92 movers (FAM:SF-CHT-057)."
   },
   {
    "code": "LABEL_ERROR",
    "text": "Play-type labels failed audits: OTHER inflated by foul endings, DRIVE under the foul benchmark, and only 0.7% mapping via initiation_type (FAM:SF-CHT-025, FAM:SF-APPM-014)."
   },
   {
    "code": "MEASURE_RELIABILITY",
    "text": "No validated cut-share or drive-share measure exists in the available data, and the PNR share jump may reflect tagging (FAM:SF-APPS-012)."
   },
   {
    "code": "CONFOUNDING",
    "text": "Team quality and menu similarity confounded earlier connector and impact results (FAM:SF-CHT-087, FAM:SF-CHT-029, FAM:SF08)."
   }
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": ["FAM:SF-CHT-057", "FAM:SF-CHT-087", "FAM:SF-CHT-025", "FAM:SF-APPM-014", "FAM:SF-APPS-011"],
  "summary": "A related cut-vs-drive portability result exists for connectors (FAM:SF-CHT-057, supported at n=92), but it does not answer the question as posed for shapers at n=24. Its follow-up (FAM:SF-CHT-087) found the population-level result to be partly confounded. Label audits (FAM:SF-CHT-025, FAM:SF-APPM-014) show the cut/drive measures are unreliable. The regular-season-to-playoff drive decline (FAM:SF-APPS-011) is supported but is a descriptive, CI-free team comparison."
 },
 "risks": [
  {"code": "SAMPLE_SIZE_POWER", "text": "n=24 units cannot detect the modest effect size seen in the prior supported study (FAM:SF-CHT-057, n=92)."},
  {"code": "LABEL_ERROR", "text": "Cut and drive labels carry foul-ending and OTHER-bucket contamination (FAM:SF-CHT-025, FAM:SF-APPM-014)."},
  {"code": "MEASURE_RELIABILITY", "text": "Cut and drive shares built from initiation_type cover only 0.7% of possessions, so the share estimates are unreliable."},
  {"code": "EXPOSURE_SPARSITY", "text": "Per-player or per-unit cut and drive counts may be too sparse in a 24-unit sample to form stable shares."},
  {"code": "CONFOUNDING", "text": "Team quality, usage and menu similarity can produce spurious portability differences (FAM:SF-CHT-087, FAM:SF-CHT-029, FAM:SF08)."},
  {"code": "OUTCOME_DERIVED_LABEL", "text": "If portability is defined from the same possession outcomes used to label the role, the test is circular."},
  {"code": "MULTIPLE_TESTING", "text": "Multiple play types, lags and context splits would inflate false positives if all are tested."},
  {"code": "DRIFT_NONSTATIONARITY", "text": "Regular-season and playoff play-type behaviour differ (FAM:SF-APPS-011, FAM:SF-APPS-012), so a pooled comparison can mix context shifts with role effects."},
  {"code": "BASE_RATE", "text": "Foul and OTHER base rates differ by play type, so PPP comparisons across types are biased without adjustment."},
  {"code": "PLACEBO_DEPENDENCE", "text": "A placebo or falsification comparison may be unavailable without a validated baseline role measure."}
 ],
 "predicted_outcome": {
  "supported": 0.08,
  "rejected": 0.10,
  "untestable": 0.45,
  "artifact": 0.20,
  "uncertain": 0.17
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Difference in the share of role that is reproduced after a unit's context change, comparing cut-heavy vs drive-heavy units. Portability must be defined before analysis; it must not use the outcome that defines the role.",
  "unit": "Player-season or team-season unit, as defined in the pre-registration. The 24 units are not yet specified.",
  "sample": "Minimum viable test: pool all available units from the 2022-23 to 2025-26 regular seasons (2025-26 playoffs only once complete, which holds from 2026-06-21) to raise n above 24. The existing 24-unit set is insufficient on its own.",
  "power": "With n=24, detectable |rho| is about 0.54 at 80% power and alpha 0.05 (two-sided). A pre-registered test must show it can detect the effect size from FAM:SF-CHT-057 (|rho| about 0.27), which needs roughly n=120-130 units. Confirm this before any analysis.",
  "controls": "Validate cut and drive labels against foul-ending and OTHER-bucket audits before use; exclude OTHER from the denominator; adjust for minutes, usage, team quality and within-team baseline (as in FAM:SF-CHT-029); adjust for menu similarity (as in FAM:SF-CHT-087).",
  "falsification": "Repeat the same portability test on a placebo play type with no hypothesised role link. Also shuffle the cut/drive labels (5000 shuffles as in FAM:SF-CHT-057). A real effect should exceed both.",
  "multiplicity": "One pre-registered primary contrast (cut-share vs portability). All other play types, lags and context splits are secondary and reported as exploratory, with Holm adjustment if reported as confirmatory.",
  "decision_rule": "Call the question supported only if the primary Spearman rho is positive with a 95% CI excluding 0, label validation passes, and the placebo and shuffle tests fail to match the primary result. Call it artifact if the result disappears after within-team baseline or menu-similarity adjustment. Otherwise report inconclusive.",
  "data_version": "NBA regular seasons 2022-23 to 2025-26 (2025-26 complete from 2026-04-13); playoffs 2022-23 to 2024-25 and 2025-26 complete from 2026-06-21. Exclude any partial files."
 }
}

